        <div class="relative mt-5">
            <div class="vertical-bar"></div>
            <div v-for="(exp, index) in jobs" :key="index" class="mb-[1rem] relative flex items-start"
                :class="index % 2 === 0 ? 'flex-row' : 'flex-row-reverse'">
                <div class="w-1/2 px-[2rem]">
                    <div class="card-experience">
                        <h3 class="fs-5 font-semibold">{{ exp.title }}</h3>
